const updateScript = `-- name: UpdateScript :one
UPDATE scripts SET
    name = $1,
    description = $2,
    interpreter = $3,
    content = $4,
    run_as = $5,
    timeout_seconds = $6,
    params = $7,
    updated_by = $8,
    updated_at = now()
WHERE id = $9
RETURNING id, workspace_id, name, description, interpreter, content, run_as, timeout_seconds, params, created_by, updated_by, created_at, updated_at
`

type UpdateScriptParams struct {
	Name           string     `json:"name"`
	Description    string     `json:"description"`
	Interpreter    string     `json:"interpreter"`
	Content        string     `json:"content"`
	RunAs          string     `json:"run_as"`
	TimeoutSeconds int32      `json:"timeout_seconds"`
	Params         []byte     `json:"params"`
	UpdatedBy      *uuid.UUID `json:"updated_by"`
	ID             uuid.UUID  `json:"id"`
}

func (q *Queries) UpdateScript(ctx context.Context, arg UpdateScriptParams) (Script, error) {
	row := q.db.QueryRow(ctx, updateScript,
		arg.Name,
		arg.Description,
		arg.Interpreter,
		arg.Content,
		arg.RunAs,
		arg.TimeoutSeconds,
		arg.Params,
		arg.UpdatedBy,
		arg.ID,
	)
	var i Script
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.Interpreter,
		&i.Content,
		&i.RunAs,
		&i.TimeoutSeconds,
		&i.Params,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
